(3718276, 520824, 76062, '<td valign="top">Heh.  Clever idea.  Must be a low density drive.  :-)<br/> <br/>I like the high contrast.  Maybe a glow on the other side would help impart the idea of a hard impact better?</td>', 'Heh.  Clever idea.  Must be a low density drive.  :-) I like the high contrast.  Maybe a glow on the other side would help impart the idea of a hard impact better?', '2007-05-31 02:37:01.000000', NULL, 1),
(3718283, 521866, 76062, '<td valign="top">Whassis?  Seems like something from a star trek episode.  :-)<br/> <br/>Looks like it was tough to photograph whatever it was.</td>', 'Whassis?  Seems like something from a star trek episode.  :-) Looks like it was tough to photograph whatever it was.', '2007-05-31 02:40:05.000000', NULL, 1),
(3718287, 523730, 76062, '<td valign="top">I like it.  Not sure what he''s hiding from, but I like it.  :-)</td>', 'I like it.  Not sure what he''s hiding from, but I like it.  :-)', '2007-05-31 02:41:04.000000', NULL, 1),
(3718291, 523677, 76062, '<td valign="top">I really like this.  Very nicely composed.  Not sure how you got the selective focus (lensbaby or warped surface?).  Neat.</td>', 'I really like this.  Very nicely composed.  Not sure how you got the selective focus (lensbaby or warped surface?).  Neat.', '2007-05-31 02:42:22.000000', NULL, 1),
(3718292, 523690, 76062, '<td valign="top">Nicely done.</td>', 'Nicely done.', '2007-05-31 02:43:01.000000', NULL, 1),
(3718299, 522915, 76062, '<td valign="top">Scary looking critter.  :-)<br/> <br/>Not sure about the composition -- seems lacking somehow (almost too close on the subject, want more negative space especially toward the top).</td>', 'Scary looking critter.  :-) Not sure about the composition -- seems lacking somehow (almost too close on the subject, want more negative space especially toward the top).', '2007-05-31 02:45:32.000000', NULL, 1),
(3718300, 523565, 76062, '<td valign="top">Nice composition.  I like the DOF choice.</td>', 'Nice composition.  I like the DOF choice.', '2007-05-31 02:46:10.000000', NULL, 1),
(3718304, 519937, 76062, '<td valign="top">Cute.  I like the warm lighting.</td>', 'Cute.  I like the warm lighting.', '2007-05-31 02:47:18.000000', NULL, 1),
(3718309, 524030, 76062, '<td valign="top">Very, very nicely done.  Gorgeous.  I really want to know how much (or little) of this was done in photoshop.</td>', 'Very, very nicely done.  Gorgeous.  I really want to know how much (or little) of this was done in photoshop.', '2007-05-31 02:49:36.000000', NULL, 1),
(3718313, 523420, 76062, '<td valign="top">Wish there was a bit more smoke.  Nice post-processing work.</td>', 'Wish there was a bit more smoke.  Nice post-processing work.', '2007-05-31 02:51:56.000000', NULL, 1),
(3718314, 523549, 76062, '<td valign="top">I love it!  Very well executed.</td>', 'I love it!  Very well executed.', '2007-05-31 02:52:40.000000', NULL, 1),
(3718317, 523746, 76062, '<td valign="top">I don''t think I quite get it.  The magic is something moving onto/off of the stage?  Sorry -- I think I''m just missing the concept.</td>', 'I don''t think I quite get it.  The magic is something moving onto/off of the stage?  Sorry -- I think I''m just missing the concept.', '2007-05-31 02:54:27.000000', NULL, 1),
(3718319, 522063, 76062, '<td valign="top">That is a disturbing image.  Very nice post-processing -- those glows are something.</td>', 'That is a disturbing image.  Very nice post-processing -- those glows are something.', '2007-05-31 02:56:10.000000', NULL, 1),
(3718331, 522886, 76062, '<td valign="top">Okay, the second entry so far that made me run to google and wikipedia for terminology.... :-)<br/> <br/>Well titled.  Nicely photographed, too.  I think the reflection is of a multipaned window with view of blue skys and fluffy clouds?<br/> <br/>The little bubble on the left is too high-contrast for me, though.  Just too distracting -- it detracts from the composition.</td>', 'Okay, the second entry so far that made me run to google and wikipedia for terminology.... :-) Well titled.  Nicely photographed, too.  I think the reflection is of a multipaned window with view of blue skys and fluffy clouds? The little bubble on the left is too high-contrast for me, though.  Just too distracting -- it detracts from the composition.', '2007-05-31 03:00:24.000000', NULL, 1),
(3718336, 523537, 76062, '<td valign="top">Just doesn''t work for me.  My eyes want more light on the subject.</td>', 'Just doesn''t work for me.  My eyes want more light on the subject.', '2007-05-31 03:01:31.000000', NULL, 1),
(3718340, 523440, 76062, '<td valign="top">Well executed, though the shadows seem to have lost a lot of detail (probably mostly due to the contest restrictions on submissions).  I like the composition, and B&amp;W seems to work well.  Not sure it screams "science" to me, though.</td>', 'Well executed, though the shadows seem to have lost a lot of detail (probably mostly due to the contest restrictions on submissions).  I like the composition, and B&W seems to work well.  Not sure it screams "science" to me, though.', '2007-05-31 03:03:38.000000', NULL, 1),
(3718341, 523770, 76062, '<td valign="top">Interesting.  I think the water in the background heightens the effect.</td>', 'Interesting.  I think the water in the background heightens the effect.', '2007-05-31 03:04:54.000000', NULL, 1),
(3718344, 523789, 76062, '<td valign="top">That bottom layer/shadow looks just a tad out of level somehow.  Interesting image regardless.</td>', 'That bottom layer/shadow looks just a tad out of level somehow.  Interesting image regardless.', '2007-05-31 03:06:40.000000', NULL, 1),
(3718346, 520460, 76062, '<td valign="top">I''ve never tried to hotograph flames like this, so I''m not much of a judge.  Seems well executed, though.</td>', 'I''ve never tried to hotograph flames like this, so I''m not much of a judge.  Seems well executed, though.', '2007-05-31 03:08:00.000000', NULL, 1),
(3718349, 524214, 76062, '<td valign="top">A cleaner glass or some spot cloning would definitely improve the image.</td>', 'A cleaner glass or some spot cloning would definitely improve the image.', '2007-05-31 03:09:00.000000', NULL, 1),
(3718352, 520072, 76062, '<td valign="top">Not sure if its the hard light from a flash or post-processing, but the lighting is a bit harsh.</td>', 'Not sure if its the hard light from a flash or post-processing, but the lighting is a bit harsh.', '2007-05-31 03:10:58.000000', NULL, 1),
(3718354, 521990, 76062, '<td valign="top">Biology is the dissection of frogs and snakes!<br/> <br/>Nicely done macro -- how''d you talk them into keeping their eyes in the same plane? :-)</td>', 'Biology is the dissection of frogs and snakes! Nicely done macro -- how''d you talk them into keeping their eyes in the same plane? :-)', '2007-05-31 03:12:23.000000', NULL, 1),
(3718356, 522698, 76062, '<td valign="top">LOVELY lighting.  The backlight works extremely well here.  Very nicely done.<br/> <br/>I can make out a child in a dark shirt, the photographer, a window or other light source, and an unused lamp in the reflection of stuff behind the lens.  Shooting through a dark drape of some sort might have improved the image.</td>', 'LOVELY lighting.  The backlight works extremely well here.  Very nicely done. I can make out a child in a dark shirt, the photographer, a window or other light source, and an unused lamp in the reflection of stuff behind the lens.  Shooting through a dark drape of some sort might have improved the image.', '2007-05-31 03:15:53.000000', NULL, 1),
(3718357, 523174, 76062, '<td valign="top">Certainly colorful.  :-)</td>', 'Certainly colorful.  :-)', '2007-05-31 03:16:23.000000', NULL, 1),
(3718358, 521187, 76062, '<td valign="top">Gosh I like star trails.  I''ve got to try it sometime.</td>', 'Gosh I like star trails.  I''ve got to try it sometime.', '2007-05-31 03:16:58.000000', NULL, 1),
(3718360, 523990, 76062, '<td valign="top">I would be so-o-o-o-o-o tempted to try to make those shadows in the tree spell something clever.  All I can see is "NY Yes", though.</td>', 'I would be so-o-o-o-o-o tempted to try to make those shadows in the tree spell something clever.  All I can see is "NY Yes", though.', '2007-05-31 03:18:39.000000', NULL, 1),
(3718361, 523151, 76062, '<td valign="top">Ooooooh.  Cool image.</td>', 'Ooooooh.  Cool image.', '2007-05-31 03:19:07.000000', NULL, 1),
(3718363, 523149, 76062, '<td valign="top">If the CPU heatsink is the subject, it should probably be completely in focus.  As it is, my eyes don''t know where to rest.</td>', 'If the CPU heatsink is the subject, it should probably be completely in focus.  As it is, my eyes don''t know where to rest.', '2007-05-31 03:20:45.000000', NULL, 1),
(3718369, 522598, 76062, '<td valign="top">They are makign a heart shape, too.  Turn it 90 degrees counter-clockwise and I think it might even be a more interesting composition.  I''d also want to blur, smudge or otherwise mute that one high-contrast spike coming in from the top in the background.  It''s a bit distracting from the image.</td>', 'They are makign a heart shape, too.  Turn it 90 degrees counter-clockwise and I think it might even be a more interesting composition.  I''d also want to blur, smudge or otherwise mute that one high-contrast spike coming in from the top in the background.  It''s a bit distracting from the image.', '2007-05-31 03:25:26.000000', NULL, 1),
(3718371, 524206, 76062, '<td valign="top">Interesting idea.</td>', 'Interesting idea.', '2007-05-31 03:27:59.000000', NULL, 1),
(3718372, 523689, 76062, '<td valign="top">It doesn''t scream "science" to me, but it''s a pretty image.  There is just enough of the plant in the background showing to detract from the image (advanced rules let you clone it out, right?).  Also the blowout in the lower right petal is just too overwhelming to me.</td>', 'It doesn''t scream "science" to me, but it''s a pretty image.  There is just enough of the plant in the background showing to detract from the image (advanced rules let you clone it out, right?).  Also the blowout in the lower right petal is just too overwhelming to me.', '2007-05-31 03:30:09.000000', NULL, 1),
(3718373, 523468, 76062, '<td valign="top">I suspect a child''s paint-by-numbers set has been abused in the name of photographic science! :-)<br/> <br/>Nice colors.  I think the image might be improved if the focus was either toward the front or back, but not dead center.</td>', 'I suspect a child''s paint-by-numbers set has been abused in the name of photographic science! :-) Nice colors.  I think the image might be improved if the focus was either toward the front or back, but not dead center.', '2007-05-31 03:32:46.000000', NULL, 1),
(3718376, 523922, 76062, '<td valign="top">Nicely lit and photographed.</td>', 'Nicely lit and photographed.', '2007-05-31 03:33:32.000000', NULL, 1),
(3718378, 523159, 76062, '<td valign="top">Made me laugh!</td>', 'Made me laugh!', '2007-05-31 03:33:54.000000', NULL, 1),
(3718380, 520911, 76062, '<td valign="top">Nice idea.</td>', 'Nice idea.', '2007-05-31 03:34:31.000000', NULL, 1),
(3718382, 523826, 76062, '<td valign="top">Nicely done.</td>', 'Nicely done.', '2007-05-31 03:35:43.000000', NULL, 1),
(3718506, 523244, 70265, '<td valign="top">Nice!</td>', 'Nice!', '2007-05-31 06:31:28.000000', NULL, 1),
(3718507, 523504, 70265, '<td valign="top">Awwww .... this is cute (and a great shot)!</td>', 'Awwww .... this is cute (and a great shot)!', '2007-05-31 06:31:30.000000', NULL, 1),
(3718508, 523512, 70265, '<td valign="top">My favorite in tthe challenge! 10</td>', 'My favorite in tthe challenge! 10', '2007-05-31 06:31:49.000000', NULL, 1),
(3718715, 524037, 13829, '<td valign="top">Hilarious! :) Plus, I really like her facial expression, and eyes. Congrats, and good luck!</td>', 'Hilarious! :) Plus, I really like her facial expression, and eyes. Congrats, and good luck!', '2007-05-31 09:22:40.000000', NULL, 1),
(3718764, 521531, 58728, '<td valign="top">I like the B&amp;W choice.  Nicely done.</td>', 'I like the B&W choice.  Nicely done.', '2007-05-31 09:52:09.000000', NULL, 1),
(3718776, 524025, 7628, '<td valign="top">great idea!  Wish the apple were sharper.</td>', 'great idea!  Wish the apple were sharper.', '2007-05-31 09:57:12.000000', NULL, 1),
(3718780, 524180, 7628, '<td valign="top">lovely colors and lighting.  Wish there were more empty blue space to the left rather than to the right - space for the jelly fish to swim into would work better as a composition.</td>', 'lovely colors and lighting.  Wish there were more empty blue space to the left rather than to the right - space for the jelly fish to swim into would work better as a composition.', '2007-05-31 09:59:32.000000', NULL, 1),
(3718795, 522915, 7628, '<td valign="top">Nice detail, good simple composition.  Wish the contrast were better - the white don''t seem really white and the blacks don''t seem really black.  Levels or curves in photoshop would make this image really pop!</td>', 'Nice detail, good simple composition.  Wish the contrast were better - the white don''t seem really white and the blacks don''t seem really black.  Levels or curves in photoshop would make this image really pop!', '2007-05-31 10:04:35.000000', NULL, 1),
(3718797, 523559, 9111, '<td valign="top">5</td>', '5', '2007-05-31 10:04:45.000000', NULL, 1),
(3718865, 523181, 38032, '<td valign="top">There are always one or two images in a challenge where I think: "I wish I did that!"  this is one of those.  Beautiful.  It does seem strange that the clips are a bit soft but this is all about the reflection I suppose.</td>', 'There are always one or two images in a challenge where I think: "I wish I did that!"  this is one of those.  Beautiful.  It does seem strange that the clips are a bit soft but this is all about the reflection I suppose.', '2007-05-31 10:37:34.000000', NULL, 1),
(3718870, 521105, 67152, '<td valign="top">Great image - love the lighting on the beak.</td>', 'Great image - love the lighting on the beak.', '2007-05-31 10:41:28.000000', NULL, 1),
(3718889, 519927, 63360, '<td valign="top">I like the perspective and DOF.  The white area on the right is a bit distracting.</td>', 'I like the perspective and DOF.  The white area on the right is a bit distracting.', '2007-05-31 10:52:43.000000', NULL, 1),
(3718897, 521484, 63360, '<td valign="top">Like your idea!  Having a child in this certainly makes for a more interesting photo.  I think that cropping a bit more of the hands would place more focus on the crystals.  Also, it would be better with more light on the crystals.</td>', 'Like your idea!  Having a child in this certainly makes for a more interesting photo.  I think that cropping a bit more of the hands would place more focus on the crystals.  Also, it would be better with more light on the crystals.', '2007-05-31 10:55:24.000000', NULL, 1),
(3718911, 523315, 63360, '<td valign="top">Certainly meets the challenge.  I would like to see more of the sky (it looks beautiful) on the right, and maybe less of the ground.</td>', 'Certainly meets the challenge.  I would like to see more of the sky (it looks beautiful) on the right, and maybe less of the ground.', '2007-05-31 11:00:36.000000', NULL, 1),
(3718913, 524139, 63360, '<td valign="top">This gave me a laugh.  I would probably lose my job if I showed up showing that much cleavage!  (I teach high school science.)</td>', 'This gave me a laugh.  I would probably lose my job if I showed up showing that much cleavage!  (I teach high school science.)', '2007-05-31 11:03:31.000000', NULL, 1),
(3718932, 520477, 63360, '<td valign="top">Definitely meets the challenge.  The colorful images on the computer add a lot of interest.  I would crop out some of the lower portion of the image.</td>', 'Definitely meets the challenge.  The colorful images on the computer add a lot of interest.  I would crop out some of the lower portion of the image.', '2007-05-31 11:09:34.000000', NULL, 1),
(3718943, 519937, 63360, '<td valign="top">Like the sepia tones used here.  Would perhaps work better to have fewer items in the photo.</td>', 'Like the sepia tones used here.  Would perhaps work better to have fewer items in the photo.', '2007-05-31 11:15:36.000000', NULL, 1),
(3718948, 524061, 63360, '<td valign="top">Yummy!  Maybe crop a bit more on the right to draw more attention to the beetle.</td>', 'Yummy!  Maybe crop a bit more on the right to draw more attention to the beetle.', '2007-05-31 11:17:55.000000', NULL, 1),
(3718949, 523181, 36382, '<td valign="top">I actually tried something similar to this, but ending up not submitting.  Now I''m glad I didn''t.  Yours is far superior.  Good idea to use two paperclips to get more of the nice lines.  Very good.</td>', 'I actually tried something similar to this, but ending up not submitting.  Now I''m glad I didn''t.  Yours is far superior.  Good idea to use two paperclips to get more of the nice lines.  Very good.', '2007-05-31 11:17:58.000000', NULL, 1),
(3718954, 522944, 63360, '<td valign="top">Maybe a bit too centered.  I would like to see more bg on the right.</td>', 'Maybe a bit too centered.  I would like to see more bg on the right.', '2007-05-31 11:19:54.000000', NULL, 1),
(3718961, 522598, 63360, '<td valign="top">Quite the gymnasts.  Great capture; could possible crop out a bit more of the twig on the left.</td>', 'Quite the gymnasts.  Great capture; could possible crop out a bit more of the twig on the left.', '2007-05-31 11:22:27.000000', NULL, 1),
(3718978, 523071, 63360, '<td valign="top">I like your idea.  Colors are good, but the lighting on his face is somewhat distracting. I would crop more of the right side which would draw more attention to his beautiful eyes.</td>', 'I like your idea.  Colors are good, but the lighting on his face is somewhat distracting. I would crop more of the right side which would draw more attention to his beautiful eyes.', '2007-05-31 11:26:47.000000', NULL, 1),
(3718982, 523214, 63360, '<td valign="top">Clever idea.  Would be cool to have placed something in the center to represent the nucleus.</td>', 'Clever idea.  Would be cool to have placed something in the center to represent the nucleus.', '2007-05-31 11:28:15.000000', NULL, 1),
(3718985, 522824, 63360, '<td valign="top">Great colors and lighting.</td>', 'Great colors and lighting.', '2007-05-31 11:29:03.000000', NULL, 1),
(3718986, 523730, 63360, '<td valign="top">Great expression on his face!</td>', 'Great expression on his face!', '2007-05-31 11:30:03.000000', NULL, 1),
(3718990, 522898, 63360, '<td valign="top">Like the colors.</td>', 'Like the colors.', '2007-05-31 11:30:26.000000', NULL, 1),
(3718994, 523869, 63360, '<td valign="top">Spelunking is fun!  I like the black/white effect.</td>', 'Spelunking is fun!  I like the black/white effect.', '2007-05-31 11:33:41.000000', NULL, 1),
(3718999, 523678, 63360, '<td valign="top">I don''t get it.</td>', 'I don''t get it.', '2007-05-31 11:34:50.000000', NULL, 1),
(3719000, 524206, 63360, '<td valign="top">Nicely done!  I would crop much of the right side of this to draw more attention to just the face.</td>', 'Nicely done!  I would crop much of the right side of this to draw more attention to just the face.', '2007-05-31 11:36:25.000000', NULL, 1),
(3719001, 520149, 63360, '<td valign="top">Moth seems to be a bit OOF.  Like the lettering and your sepia tones.</td>', 'Moth seems to be a bit OOF.  Like the lettering and your sepia tones.', '2007-05-31 11:37:18.000000', NULL, 1),
(3719011, 523105, 63360, '<td valign="top">Fantastic lightning strike!  For more impact, I would crop everything out from the ground up to the middle of the trees and some of the right side.</td>', 'Fantastic lightning strike!  For more impact, I would crop everything out from the ground up to the middle of the trees and some of the right side.', '2007-05-31 11:41:07.000000', NULL, 1),
(3719019, 522825, 63360, '<td valign="top">Lovely colors/great lighting and meets the challenge.  Well done!</td>', 'Lovely colors/great lighting and meets the challenge.  Well done!', '2007-05-31 11:42:36.000000', NULL, 1),
(3719021, 524126, 63360, '<td valign="top">Cute kid!  A little too blurry and the whites are blown out.</td>', 'Cute kid!  A little too blurry and the whites are blown out.', '2007-05-31 11:43:40.000000', NULL, 1),
(3719029, 521754, 63360, '<td valign="top">Great colors.  I would crop the top 1/3 of the photo to draw more attention to the arcing.</td>', 'Great colors.  I would crop the top 1/3 of the photo to draw more attention to the arcing.', '2007-05-31 11:45:02.000000', NULL, 1),
(3719035, 521724, 63360, '<td valign="top">Visually appealing - love the symmetry, angle of your shot, and DOF!</td>', 'Visually appealing - love the symmetry, angle of your shot, and DOF!', '2007-05-31 11:45:56.000000', NULL, 1),
(3719043, 520521, 63360, '<td valign="top">Focus is good, but the colors need to be punched up a bit.</td>', 'Focus is good, but the colors need to be punched up a bit.', '2007-05-31 11:47:59.000000', NULL, 1),
(3719048, 520306, 63360, '<td valign="top">Your use of selective desat creates interest, although the red is a bit too saturated.</td>', 'Your use of selective desat creates interest, although the red is a bit too saturated.', '2007-05-31 11:51:17.000000', NULL, 1),
(3719063, 523562, 63360, '<td valign="top">Fiddleheads!  Soft focus works well here.  Might want to increase color contrast a bit to make the new frond pop.</td>', 'Fiddleheads!  Soft focus works well here.  Might want to increase color contrast a bit to make the new frond pop.', '2007-05-31 11:54:05.000000', NULL, 1),
(3719080, 523795, 63360, '<td valign="top">Nice capture.  Too much light on the subject - some of the details are lost.  Try shooting when overcast, later in the day, or providing some type of overhead cover.</td>', 'Nice capture.  Too much light on the subject - some of the details are lost.  Try shooting when overcast, later in the day, or providing some type of overhead cover.', '2007-05-31 11:59:57.000000', NULL, 1),
(3719082, 524058, 63360, '<td valign="top">Lovely lines and shadows.</td>', 'Lovely lines and shadows.', '2007-05-31 12:00:35.000000', NULL, 1),
(3719142, 523479, 79242, '<td valign="top">Great concept. Artistically I think chart could be better portrayed. The people are shot wonderfully. 10 for concept, 8 on execution.</td>', 'Great concept. Artistically I think chart could be better portrayed. The people are shot wonderfully. 10 for concept, 8 on execution.', '2007-05-31 12:32:17.000000', NULL, 1),
(3719145, 524158, 79242, '<td valign="top">In my opinion the best most well rounded "scientific" photo. Makes me feel like I am in high school biology class, and it looks beautiful.</td>', 'In my opinion the best most well rounded "scientific" photo. Makes me feel like I am in high school biology class, and it looks beautiful.', '2007-05-31 12:34:11.000000', NULL, 1),
(3719147, 522944, 79242, '<td valign="top">Very nice.</td>', 'Very nice.', '2007-05-31 12:34:30.000000', NULL, 1),
(3719148, 523504, 79242, '<td valign="top">A well shot photo, that makes me think "science". One of the few in the competition that stood out to me.</td>', 'A well shot photo, that makes me think "science". One of the few in the competition that stood out to me.', '2007-05-31 12:35:43.000000', NULL, 1),
(3719157, 523010, 79242, '<td valign="top">Great photo. Amazing. It would get a 10 if it was in a flower photo competition.</td>', 'Great photo. Amazing. It would get a 10 if it was in a flower photo competition.', '2007-05-31 12:37:56.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3719162, 523181, 28801, '<td valign="top">Super! Super!! Super!!!</td>', 'Super! Super!! Super!!!', '2007-05-31 12:39:08.000000', NULL, 1),
(3719165, 524214, 68035, '<td valign="top">Really nice idea and yep it does science for me bit of a shame about the glare on the glass but nice bokeh</td>', 'Really nice idea and yep it does science for me bit of a shame about the glare on the glass but nice bokeh', '2007-05-31 12:40:51.000000', NULL, 1),
(3719171, 523647, 68035, '<td valign="top">Super image for science love the lighting and the sharpness 9 from me</td>', 'Super image for science love the lighting and the sharpness 9 from me', '2007-05-31 12:41:53.000000', NULL, 1),
(3719177, 523247, 68035, '<td valign="top">Very creative and wonderfully executed if I am looking at any minor points I would say the light reflection on the tomato and the loss of focus on the leading root (which may well be unavoidable) detract at a very minimal level but still a fantastic 8</td>', 'Very creative and wonderfully executed if I am looking at any minor points I would say the light reflection on the tomato and the loss of focus on the leading root (which may well be unavoidable) detract at a very minimal level but still a fantastic 8', '2007-05-31 12:43:47.000000', NULL, 1),
(3719179, 523746, 68035, '<td valign="top">lovely idea and very well executed</td>', 'lovely idea and very well executed', '2007-05-31 12:44:46.000000', NULL, 1),
(3719224, 523159, 68035, '<td valign="top">Great idea made me laugh and laugh fun and creative take on the challenge whilst hitting the challenge requirements spot on...BTW has he just thought of a cure for constipation??? LOL<br/> <br/>Outstanding</td>', 'Great idea made me laugh and laugh fun and creative take on the challenge whilst hitting the challenge requirements spot on...BTW has he just thought of a cure for constipation??? LOL Outstanding', '2007-05-31 13:08:39.000000', NULL, 1),
