(3721288, 523951, 42995, '<td valign="top">What a wonderful lush shot.</td>', 'What a wonderful lush shot.', '2007-05-31 23:40:35.000000', NULL, 1),
(3721289, 522872, 42995, '<td valign="top">Great focus and texture on these.</td>', 'Great focus and texture on these.', '2007-05-31 23:40:41.000000', NULL, 1),
(3721292, 522698, 42995, '<td valign="top">I like the detail in the reflections, very nice.</td>', 'I like the detail in the reflections, very nice.', '2007-05-31 23:40:58.000000', NULL, 1),
(3721294, 523504, 42995, '<td valign="top">Great colour, lighting and composition!</td>', 'Great colour, lighting and composition!', '2007-05-31 23:41:04.000000', NULL, 1),
(3721296, 523181, 42995, '<td valign="top">Simple and effective, very nice.</td>', 'Simple and effective, very nice.', '2007-05-31 23:41:11.000000', NULL, 1),
(3721297, 522664, 42995, '<td valign="top">Fantastic macro!</td>', 'Fantastic macro!', '2007-05-31 23:41:20.000000', NULL, 1),
(3721299, 524066, 42995, '<td valign="top">This is a beautiful, beautiful shot. I only wish it was totally symmetrical: there''s more black space to the left of the subject than on the right.  Still, a fantastic shot!</td>', 'This is a beautiful, beautiful shot. I only wish it was totally symmetrical: there''s more black space to the left of the subject than on the right.  Still, a fantastic shot!', '2007-05-31 23:42:06.000000', NULL, 1),
(3721300, 523957, 42995, '<td valign="top">Simple yet beautiful.  Love the colour gradations in the liquid.</td>', 'Simple yet beautiful.  Love the colour gradations in the liquid.', '2007-05-31 23:42:22.000000', NULL, 1),
(3721301, 523786, 42995, '<td valign="top">Wonderful colours and shapes, I assume you''re including the brush on the left to fulfill the rule about ''literal artwork'', but I think the shot would have been better without it.</td>', 'Wonderful colours and shapes, I assume you''re including the brush on the left to fulfill the rule about ''literal artwork'', but I think the shot would have been better without it.', '2007-05-31 23:42:35.000000', NULL, 1),
(3721302, 524030, 42995, '<td valign="top">Very cool -- I can only imagine how much work this must have taken!</td>', 'Very cool -- I can only imagine how much work this must have taken!', '2007-05-31 23:42:57.000000', NULL, 1),
(3721307, 523159, 69572, '<td valign="top">I have seen this before.  Still Funny</td>', 'I have seen this before.  Still Funny', '2007-05-31 23:43:39.000000', NULL, 1),
(3721318, 523181, 69572, '<td valign="top">Wow that is amazing, I would love to know how you got the colours in the liquid.</td>', 'Wow that is amazing, I would love to know how you got the colours in the liquid.', '2007-05-31 23:45:33.000000', NULL, 1),
(3721320, 520068, 69572, '<td valign="top">Would have also been good for the double take challenge</td>', 'Would have also been good for the double take challenge', '2007-05-31 23:46:08.000000', NULL, 1),
(3721561, 523723, 62249, '<td valign="top">Needs more depth of field.</td>', 'Needs more depth of field.', '2007-06-01 00:50:00.000000', NULL, 1),
(3721569, 524126, 62249, '<td valign="top">Good expression on his face, and it fits the challenge theme. Needs more detail in highlights.</td>', 'Good expression on his face, and it fits the challenge theme. Needs more detail in highlights.', '2007-06-01 00:51:59.000000', NULL, 1),
(3721592, 523773, 62249, '<td valign="top">Funny. Highlights need more detail.</td>', 'Funny. Highlights need more detail.', '2007-06-01 00:55:59.000000', NULL, 1),
(3721597, 523429, 62249, '<td valign="top">You get some points for creativity, but need to work on your technical execution.</td>', 'You get some points for creativity, but need to work on your technical execution.', '2007-06-01 00:56:53.000000', NULL, 1),
(3721605, 523464, 62249, '<td valign="top">Work on the composition. The elements are too separated and don''t form a cohesive scene.</td>', 'Work on the composition. The elements are too separated and don''t form a cohesive scene.', '2007-06-01 00:58:00.000000', NULL, 1),
(3721614, 523181, 62249, '<td valign="top">Very interesting. Love the swirly effect, and DOF seems just right.</td>', 'Very interesting. Love the swirly effect, and DOF seems just right.', '2007-06-01 00:59:43.000000', NULL, 1),
(3721637, 519225, 62249, '<td valign="top">An original approach. I''m guessing that many folks will complain about the blurring and abstractness of this one, but I love it. The lighting and the focus on the face is terrific.</td>', 'An original approach. I''m guessing that many folks will complain about the blurring and abstractness of this one, but I love it. The lighting and the focus on the face is terrific.', '2007-06-01 01:05:00.000000', NULL, 1),
(3721640, 524061, 62249, '<td valign="top">Good title, good shot.</td>', 'Good title, good shot.', '2007-06-01 01:05:35.000000', NULL, 1),
(3721648, 523528, 74059, '<td valign="top">seems like a snapshot to me</td>', 'seems like a snapshot to me', '2007-06-01 01:06:00.000000', NULL, 1),
(3721663, 523303, 74059, '<td valign="top">hehe...cute shot.  I really like the color</td>', 'hehe...cute shot.  I really like the color', '2007-06-01 01:07:38.000000', NULL, 1),
(3721667, 523922, 74059, '<td valign="top">Great idea.  The sepia really works</td>', 'Great idea.  The sepia really works', '2007-06-01 01:08:24.000000', NULL, 1),
(3721679, 523723, 74059, '<td valign="top">The shadows on the leaves seem to be in odd places.  Maybe the lighting could be different.</td>', 'The shadows on the leaves seem to be in odd places.  Maybe the lighting could be different.', '2007-06-01 01:10:47.000000', NULL, 1),
(3721687, 520119, 74059, '<td valign="top">great shot of the sky...but the telephone poles are distracting.</td>', 'great shot of the sky...but the telephone poles are distracting.', '2007-06-01 01:11:38.000000', NULL, 1),
(3721696, 523677, 62249, '<td valign="top">Clever title. Think I''d like either more or less DOF. Photo seems to be at an in between spot.</td>', 'Clever title. Think I''d like either more or less DOF. Photo seems to be at an in between spot.', '2007-06-01 01:13:17.000000', NULL, 1),
(3721705, 523496, 62249, '<td valign="top">Cool looking bird and nice feather detail. Wish the lighting were so hot in the middle.</td>', 'Cool looking bird and nice feather detail. Wish the lighting were so hot in the middle.', '2007-06-01 01:14:14.000000', NULL, 1),
(3721713, 523689, 74059, '<td valign="top">great color but the shot isn''t centered</td>', 'great color but the shot isn''t centered', '2007-06-01 01:14:59.000000', NULL, 1),
(3721728, 520072, 74059, '<td valign="top">This shot needs some visual interest.  It''s a bit dull.</td>', 'This shot needs some visual interest.  It''s a bit dull.', '2007-06-01 01:17:17.000000', NULL, 1),
(3721730, 523468, 62249, '<td valign="top">Colorful. Needs sharper focus along full length of paint containers.</td>', 'Colorful. Needs sharper focus along full length of paint containers.', '2007-06-01 01:17:35.000000', NULL, 1),
(3721734, 524025, 74059, '<td valign="top">Too much of the shot is oof.</td>', 'Too much of the shot is oof.', '2007-06-01 01:18:00.000000', NULL, 1),
(3721736, 520300, 62249, '<td valign="top">Not sure how "scientific" this one is, but I enjoy colorful abstracts, and this one is attractive.</td>', 'Not sure how "scientific" this one is, but I enjoy colorful abstracts, and this one is attractive.', '2007-06-01 01:18:35.000000', NULL, 1),
(3721746, 523159, 74059, '<td valign="top">seems like there''s not enough light on his face</td>', 'seems like there''s not enough light on his face', '2007-06-01 01:19:35.000000', NULL, 1),
(3721751, 524034, 68573, '<td valign="top">I like this, the arrangement and the soft spot in the centre, nice compostion and vibrant colors</td>', 'I like this, the arrangement and the soft spot in the centre, nice compostion and vibrant colors', '2007-06-01 01:19:48.000000', NULL, 1),
