(3725403, 523990, 24550, '<td valign="top">great dreamy feel. the centered composition works well. 9.</td>', 'great dreamy feel. the centered composition works well. 9.', '2007-06-01 18:08:05.000000', NULL, 1),
(3725408, 521033, 24550, '<td valign="top">seems a bit overexposed, but great capture of the pattern .7.</td>', 'seems a bit overexposed, but great capture of the pattern .7.', '2007-06-01 18:08:31.000000', NULL, 1),
(3725413, 521202, 24550, '<td valign="top">very different image of fireworks. 9.</td>', 'very different image of fireworks. 9.', '2007-06-01 18:09:13.000000', NULL, 1),
(3725417, 523496, 60614, '<td valign="top">Composition is fine.  It looks like you used a flash so it took some details out of the bird feathers.  I like the gray tone of the bird but think the pink area around the beak would make these pop if it was brighter.  The focus seeme a little soft.  It might be fun if you played around with rotating the image to see what affect you get. IMHO</td>', 'Composition is fine.  It looks like you used a flash so it took some details out of the bird feathers.  I like the gray tone of the bird but think the pink area around the beak would make these pop if it was brighter.  The focus seeme a little soft.  It might be fun if you played around with rotating the image to see what affect you get. IMHO', '2007-06-01 18:09:35.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3725432, 521333, 60614, '<td valign="top">Looks like the wombat is asleep.  Like the DOF and the green tones in the background.  The wombat could use a little sharpening and possibly some processing to bring out the warm colors of his fur.</td>', 'Looks like the wombat is asleep.  Like the DOF and the green tones in the background.  The wombat could use a little sharpening and possibly some processing to bring out the warm colors of his fur.', '2007-06-01 18:11:35.000000', NULL, 1),
(3725443, 523532, 60614, '<td valign="top">You have some nice colors going on here but I can''t tell what it is.  The flames looks soft but that is what I like about it.</td>', 'You have some nice colors going on here but I can''t tell what it is.  The flames looks soft but that is what I like about it.', '2007-06-01 18:13:13.000000', NULL, 1),
(3725451, 521105, 902, '<td valign="top">Was this a real bird landing or a stuffed one at a museum?  A really nice shot either way</td>', 'Was this a real bird landing or a stuffed one at a museum?  A really nice shot either way', '2007-06-01 18:14:21.000000', NULL, 1),
(3725454, 523150, 60614, '<td valign="top">Like the leading line you have achieved with the geese.  I think with a more shallow DOF the the foreground goose and chicks would stand out more.  Love how each goose is doing something diffrent.</td>', 'Like the leading line you have achieved with the geese.  I think with a more shallow DOF the the foreground goose and chicks would stand out more.  Love how each goose is doing something diffrent.', '2007-06-01 18:14:35.000000', NULL, 1),
(3725472, 523812, 60614, '<td valign="top">Great composition and expression on the monkey.  I like the background colors but think the colors of the monkey need to be adjusted to make him stand out more.  I like the fact that you have the chain link fence showing in the foreground.  That gets the meaning across.</td>', 'Great composition and expression on the monkey.  I like the background colors but think the colors of the monkey need to be adjusted to make him stand out more.  I like the fact that you have the chain link fence showing in the foreground.  That gets the meaning across.', '2007-06-01 18:17:05.000000', NULL, 1),
(3725475, 523407, 902, '<td valign="top">Great action</td>', 'Great action', '2007-06-01 18:18:12.000000', NULL, 1),
(3725484, 523979, 60614, '<td valign="top">Interesting idea.  The photo is just a bit too soft.  I love the red color and the fact that you caught a crayon drip in action.  I think maybe with a different color background it would pop more (e.g. yellow).  IMHO</td>', 'Interesting idea.  The photo is just a bit too soft.  I love the red color and the fact that you caught a crayon drip in action.  I think maybe with a different color background it would pop more (e.g. yellow).  IMHO', '2007-06-01 18:19:48.000000', NULL, 1),
(3725501, 523027, 60614, '<td valign="top">Like the composition.  I think it is neat how you caught all that grass flying around the the person.  Nice crisp focus and tones.</td>', 'Like the composition.  I think it is neat how you caught all that grass flying around the the person.  Nice crisp focus and tones.', '2007-06-01 18:22:54.000000', NULL, 1),
(3725504, 523841, 72317, '<td valign="top">I''d like it better if all of the droplets were in focus.</td>', 'I''d like it better if all of the droplets were in focus.', '2007-06-01 18:23:22.000000', NULL, 1),
(3725510, 519824, 72317, '<td valign="top">That''s a toadlet..<br/>But, it''s very nice.</td>', 'That''s a toadlet..But, it''s very nice.', '2007-06-01 18:25:17.000000', NULL, 1),
(3725523, 521683, 72317, '<td valign="top">Seems out of focus. I would like this alot in black and white, but that''s a personal opinion.</td>', 'Seems out of focus. I would like this alot in black and white, but that''s a personal opinion.', '2007-06-01 18:27:32.000000', NULL, 1),
(3725526, 524139, 72317, '<td valign="top">Awwwh.. Mine was a man.. A very old man..<br/> <br/>I think this will do very very well if it doesn''t ribbon.</td>', 'Awwwh.. Mine was a man.. A very old man.. I think this will do very very well if it doesn''t ribbon.', '2007-06-01 18:28:06.000000', NULL, 1),
(3725546, 522675, 72317, '<td valign="top">Very very good.<br/>I used to breed these little suckers for the LaPorte 4H club.. If this happens to be your pet, they really like old autumn leaves and a bit of fresh dirt in their cages, but the moss is very good for keeping them moist.<br/>=)</td>', 'Very very good.I used to breed these little suckers for the LaPorte 4H club.. If this happens to be your pet, they really like old autumn leaves and a bit of fresh dirt in their cages, but the moss is very good for keeping them moist.=)', '2007-06-01 18:30:27.000000', NULL, 1),
(3725555, 523150, 72317, '<td valign="top">Goslings are so cute. Very nice image. I love the coloring the very most. Looks natural, yet bright and clear. Very nice image.</td>', 'Goslings are so cute. Very nice image. I love the coloring the very most. Looks natural, yet bright and clear. Very nice image.', '2007-06-01 18:31:26.000000', NULL, 1),
(3725559, 522474, 72317, '<td valign="top">Not a fan of the green or the facial expression. Otherwise this is an exceptional image.</td>', 'Not a fan of the green or the facial expression. Otherwise this is an exceptional image.', '2007-06-01 18:32:02.000000', NULL, 1),
(3725561, 522886, 72317, '<td valign="top">O.O How did you do that?</td>', 'O.O How did you do that?', '2007-06-01 18:32:31.000000', NULL, 1),
(3725562, 523315, 72317, '<td valign="top">Wow! GREAT clarity and detail!</td>', 'Wow! GREAT clarity and detail!', '2007-06-01 18:32:55.000000', NULL, 1),
(3725568, 523770, 72317, '<td valign="top">I''d try using different, more active/interesting shadows next time..</td>', 'I''d try using different, more active/interesting shadows next time..', '2007-06-01 18:34:00.000000', NULL, 1),
(3725593, 524030, 72317, '<td valign="top">That''s awesome. Great idea. Most creative image I have seen yet this whole challenge. I don''t think it will ribbon, and I will give my opinion.<br/> <br/>I am going to make a guess; this image was taken outdoors on grass in the evening.<br/> <br/>I would like it with slightly softer lighting and a solid black background. I think it would ribbon, too.<br/> <br/>But don''t listen to me, because half of the time I don''t know what I''m talking about.<br/>=P<br/> <br/>Well, good luck. I''m boosting you up as best I can with a vote of ten.</td>', 'That''s awesome. Great idea. Most creative image I have seen yet this whole challenge. I don''t think it will ribbon, and I will give my opinion. I am going to make a guess; this image was taken outdoors on grass in the evening. I would like it with slightly softer lighting and a solid black background. I think it would ribbon, too. But don''t listen to me, because half of the time I don''t know what I''m talking about.=P Well, good luck. I''m boosting you up as best I can with a vote of ten.', '2007-06-01 18:37:17.000000', NULL, 1),
(3725600, 523689, 72317, '<td valign="top">Lower right hand area of the flower looks too bright. I think a lower ISO would have done you a bit better.</td>', 'Lower right hand area of the flower looks too bright. I think a lower ISO would have done you a bit better.', '2007-06-01 18:38:10.000000', NULL, 1),
(3725610, 524126, 72317, '<td valign="top">Too blurry. Try to keep your model as still as possible. Orange, purple, and yellow in the background are a bit distracting. Your model sort of looks like he''s doing the robot.. Just an observation.. xD</td>', 'Too blurry. Try to keep your model as still as possible. Orange, purple, and yellow in the background are a bit distracting. Your model sort of looks like he''s doing the robot.. Just an observation.. xD', '2007-06-01 18:39:45.000000', NULL, 1),
(3725619, 523804, 72317, '<td valign="top">Ew..<br/>But nice picture..<br/>xD</td>', 'Ew..But nice picture..xD', '2007-06-01 18:41:19.000000', NULL, 1),
(3725624, 524087, 72317, '<td valign="top">Don''t you hate injections? God.. I can''t stand them..<br/> <br/>Nice clarity, and nice detail. Would have liked a solid background, but that''s just me.</td>', 'Don''t you hate injections? God.. I can''t stand them.. Nice clarity, and nice detail. Would have liked a solid background, but that''s just me.', '2007-06-01 18:42:11.000000', NULL, 1),
(3725637, 523795, 72317, '<td valign="top">Judging by the feet, I''m guessing a treefrog of some sort?<br/> <br/>Very nice picture. Nice colors too.</td>', 'Judging by the feet, I''m guessing a treefrog of some sort? Very nice picture. Nice colors too.', '2007-06-01 18:43:52.000000', NULL, 1),
(3725641, 523577, 72317, '<td valign="top">I liked the other one alot better.. Nice try though. This one is a bit grainy. Try a lower ISO.</td>', 'I liked the other one alot better.. Nice try though. This one is a bit grainy. Try a lower ISO.', '2007-06-01 18:45:34.000000', NULL, 1),
(3725647, 524138, 72317, '<td valign="top">A bit white.. Try a background that isn''t so bright, if that''s possible. I think this shot has great potential.</td>', 'A bit white.. Try a background that isn''t so bright, if that''s possible. I think this shot has great potential.', '2007-06-01 18:48:24.000000', NULL, 1),
