(3728648, 522970, 63360, '<td valign="top">This looks very close and dangerous!  I think this would be better if the rattle was in focus.</td>', 'This looks very close and dangerous!  I think this would be better if the rattle was in focus.', '2007-06-02 12:38:10.000000', NULL, 1),
(3728653, 522698, 63360, '<td valign="top">Composition and lighting are good.  I like the way the fingertips create that red glow.  Maybe clone out the hairs on the arm which are visible on the black bg so as not to distract from the subject.</td>', 'Composition and lighting are good.  I like the way the fingertips create that red glow.  Maybe clone out the hairs on the arm which are visible on the black bg so as not to distract from the subject.', '2007-06-02 12:40:23.000000', NULL, 1),
(3728660, 524208, 63360, '<td valign="top">Cute title and great expression.  I think this could be improved by adding more light to the left side, crop some of the top area, a little sharper focus.  Good luck!</td>', 'Cute title and great expression.  I think this could be improved by adding more light to the left side, crop some of the top area, a little sharper focus.  Good luck!', '2007-06-02 12:43:38.000000', NULL, 1),
