(3734709, 524025, 63360, '<td valign="top">The apple does not really appear to be a part of the picture.  Perhaps having someone (Newton?) in the photo with the apple to scale would work better.</td>', 'The apple does not really appear to be a part of the picture.  Perhaps having someone (Newton?) in the photo with the apple to scale would work better.', '2007-06-04 00:48:40.000000', NULL, 1),
(3734712, 524214, 60047, '<td valign="top">I have no idea what I am looking at. The colors are neutral. The composition is somewhat simple. What''s going on, here?</td>', 'I have no idea what I am looking at. The colors are neutral. The composition is somewhat simple. What''s going on, here?', '2007-06-04 00:49:41.000000', NULL, 1),
