(3734718, 523528, 60047, '<td valign="top">Kind of a fun picture of a face - but the title doesn''t work since the face is not in the sun like the back of the head and the shirt is... this seems too contrived.</td>', 'Kind of a fun picture of a face - but the title doesn''t work since the face is not in the sun like the back of the head and the shirt is... this seems too contrived.', '2007-06-04 00:51:26.000000', NULL, 1),
(3734727, 520072, 60047, '<td valign="top">This has a flat, snapshot appearance. Perhaps a tighter crop on the subject and  the telescope might be more visually appealing?</td>', 'This has a flat, snapshot appearance. Perhaps a tighter crop on the subject and  the telescope might be more visually appealing?', '2007-06-04 00:53:21.000000', NULL, 1),
(3734729, 524143, 63360, '<td valign="top">I like your use of  desaturation, negative space, and reflections. Simple and effective!</td>', 'I like your use of  desaturation, negative space, and reflections. Simple and effective!', '2007-06-04 00:53:56.000000', NULL, 1),
(3734732, 520238, 60047, '<td valign="top">Pretty harsh light to work with on this shot. Subject appears to be out of focus, slightly.</td>', 'Pretty harsh light to work with on this shot. Subject appears to be out of focus, slightly.', '2007-06-04 00:54:21.000000', NULL, 1),
