(3736819, 523150, 63360, '<td valign="top">Nicely focused. Needs to be a little brighter, as I find it difficult to see a lot of detail in the black areas.</td>', 'Nicely focused. Needs to be a little brighter, as I find it difficult to see a lot of detail in the black areas.', '2007-06-04 12:43:42.000000', NULL, 1),
(3736849, 523429, 63360, '<td valign="top">The noise and glare of this photo is quite fitting with your title.  Very creative.</td>', 'The noise and glare of this photo is quite fitting with your title.  Very creative.', '2007-06-04 12:50:03.000000', NULL, 1),
(3736855, 524218, 63360, '<td valign="top">Overhead lighting is too harsh, which has washed out the colors and details.  Try shooting at a different time of day, or use something to diffuse the light.</td>', 'Overhead lighting is too harsh, which has washed out the colors and details.  Try shooting at a different time of day, or use something to diffuse the light.', '2007-06-04 12:51:15.000000', NULL, 1),
(3736858, 523854, 63360, '<td valign="top">I like your use of colors, especially the bg.</td>', 'I like your use of colors, especially the bg.', '2007-06-04 12:51:43.000000', NULL, 1),
(3736861, 523647, 63360, '<td valign="top">Purple power!  The black lines create interest here.</td>', 'Purple power!  The black lines create interest here.', '2007-06-04 12:52:35.000000', NULL, 1),
(3736880, 524143, 73658, '<td valign="top">Simple but effective !</td>', 'Simple but effective !', '2007-06-04 12:59:52.000000', NULL, 1),
(3736882, 523896, 63360, '<td valign="top">Nice macro.  I especially like the details on the antenna of this butterfly.  The whites a a bit blown on the flower.</td>', 'Nice macro.  I especially like the details on the antenna of this butterfly.  The whites a a bit blown on the flower.', '2007-06-04 13:01:53.000000', NULL, 1),
(3736884, 524121, 63360, '<td valign="top">Like the DOF, but the colors appear washed out.  Perhaps diffuse the overhead lighting or shoot at a different time of day.  Also, the main subject appears to be the flowers.</td>', 'Like the DOF, but the colors appear washed out.  Perhaps diffuse the overhead lighting or shoot at a different time of day.  Also, the main subject appears to be the flowers.', '2007-06-04 13:03:20.000000', NULL, 1),
(3736890, 524009, 63360, '<td valign="top">Pretty markings!  Lighting appears too harsh and has created some glare.</td>', 'Pretty markings!  Lighting appears too harsh and has created some glare.', '2007-06-04 13:04:57.000000', NULL, 1),
(3736894, 524216, 63360, '<td valign="top">Like the colors and your idea for shooting this from above.  I think it might be better against a totally black bg.</td>', 'Like the colors and your idea for shooting this from above.  I think it might be better against a totally black bg.', '2007-06-04 13:06:02.000000', NULL, 1),
(3736901, 523170, 63360, '<td valign="top">Ferns have such a beautiful structure.  I think you might get better details if the lighting was more even.</td>', 'Ferns have such a beautiful structure.  I think you might get better details if the lighting was more even.', '2007-06-04 13:07:59.000000', NULL, 1),
(3736910, 522959, 63360, '<td valign="top">I like the diffuse lighting used here, but some of the details have been lost.</td>', 'I like the diffuse lighting used here, but some of the details have been lost.', '2007-06-04 13:09:22.000000', NULL, 1),
(3736921, 523951, 63360, '<td valign="top">Good macro - I like the details, colors, and DOF.  A square crop might improve this fantastic shot.</td>', 'Good macro - I like the details, colors, and DOF.  A square crop might improve this fantastic shot.', '2007-06-04 13:10:40.000000', NULL, 1),
(3736926, 523174, 63360, '<td valign="top">Good lighting and composition!  Nice and clean shot.</td>', 'Good lighting and composition!  Nice and clean shot.', '2007-06-04 13:11:27.000000', NULL, 1),
(3736936, 523846, 63360, '<td valign="top">Praying mantids are very cool.  Would love to see the whole insect, especially it''s front legs.  Lighting needs to be diffused a bit.</td>', 'Praying mantids are very cool.  Would love to see the whole insect, especially it''s front legs.  Lighting needs to be diffused a bit.', '2007-06-04 13:13:38.000000', NULL, 1),
(3736947, 523677, 63360, '<td valign="top">Great magnetic lines.  I like your use of desaturation and a clever title.  Could be improved by shooting at a slightly different angle and a smaller aperture to get more lines in focus.</td>', 'Great magnetic lines.  I like your use of desaturation and a clever title.  Could be improved by shooting at a slightly different angle and a smaller aperture to get more lines in focus.', '2007-06-04 13:15:40.000000', NULL, 1),
(3736955, 521548, 63360, '<td valign="top">Good composition.  I like the noise seen in the sky and how the lights in the foreground repeat the starburst of the fireworks.</td>', 'Good composition.  I like the noise seen in the sky and how the lights in the foreground repeat the starburst of the fireworks.', '2007-06-04 13:17:41.000000', NULL, 1),
(3736958, 524125, 63360, '<td valign="top">Ha!  Which "planet" is this?  Nice motion blur.  Lighting is good, too.</td>', 'Ha!  Which "planet" is this?  Nice motion blur.  Lighting is good, too.', '2007-06-04 13:18:50.000000', NULL, 1),
(3736968, 522886, 63360, '<td valign="top">Cool - bubbles imitating life!  Could be like Volvox.  I would clone out the two other bubbles.</td>', 'Cool - bubbles imitating life!  Could be like Volvox.  I would clone out the two other bubbles.', '2007-06-04 13:20:30.000000', NULL, 1),
(3737248, 523548, 39880, '<td valign="top">Not sure what''s going on here because most of it is too dark.  Maybe lighten it up a bit.  Exposure seems off.</td>', 'Not sure what''s going on here because most of it is too dark.  Maybe lighten it up a bit.  Exposure seems off.', '2007-06-04 14:25:19.000000', NULL, 1),
