(3740401, 519937, 76430, '<td valign="top">Very imaginitive, well composed, great focus throughout.  Interesting blend of ancient arts with the Internet.</td>', 'Very imaginitive, well composed, great focus throughout.  Interesting blend of ancient arts with the Internet.', '2007-06-05 02:07:16.000000', NULL, 1),
(3740409, 523504, 76430, '<td valign="top">I love this one.  A rat trying to save itself from scientific experimentation.  The green background really makes this one.</td>', 'I love this one.  A rat trying to save itself from scientific experimentation.  The green background really makes this one.', '2007-06-05 02:09:19.000000', NULL, 1),
(3740418, 521919, 76430, '<td valign="top">Another Mono Lake picture.  Great clarity, color, and title.</td>', 'Another Mono Lake picture.  Great clarity, color, and title.', '2007-06-05 02:10:58.000000', NULL, 1),
