(3740426, 522898, 76430, '<td valign="top">Beautiful picture.  Drops on a CD?  The coloring is great.  It looks like something astronomical.</td>', 'Beautiful picture.  Drops on a CD?  The coloring is great.  It looks like something astronomical.', '2007-06-05 02:14:26.000000', NULL, 1),
(3740428, 523866, 76430, '<td valign="top">Nice, but the windmill tends to blend into the sky.  Maybe a polarizing fileter would help, a different angle, or adjustment in postprocessing.</td>', 'Nice, but the windmill tends to blend into the sky.  Maybe a polarizing fileter would help, a different angle, or adjustment in postprocessing.', '2007-06-05 02:15:40.000000', NULL, 1),
