INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3740471, 524139, 76430, '<td valign="top">Now you did it.  I can''t get Van Halen out of my head.  Good creativity and execution.</td>', 'Now you did it.  I can''t get Van Halen out of my head.  Good creativity and execution.', '2007-06-05 02:34:14.000000', NULL, 1),
(3740473, 524013, 76430, '<td valign="top">Whatever it is, it''s beautiful.</td>', 'Whatever it is, it''s beautiful.', '2007-06-05 02:35:22.000000', NULL, 1),
(3740519, 523940, 79184, '<td valign="top">Nice photo :)</td>', 'Nice photo :)', '2007-06-05 03:04:15.000000', NULL, 1),
(3740716, 524125, 23430, '<td valign="top">I''m guessing this is a basket ball. It''s well done regardless.</td>', 'I''m guessing this is a basket ball. It''s well done regardless.', '2007-06-05 06:14:40.000000', NULL, 1),
(3740805, 521187, 57661, '<td valign="top">I like this photo. I don''t really like the frame. I find it not compatible with astrophotography, but good for family portrait &amp; stuff (this is my opinion, don''t forget). I am not sure the tree does very well in this photo, but I find very important something from Earth in this kind of photos. I think the constellation you focused is just (almost) perfect because of the star colors. Is the line that leads to the tree an artificial satellite?</td>', 'I like this photo. I don''t really like the frame. I find it not compatible with astrophotography, but good for family portrait & stuff (this is my opinion, don''t forget). I am not sure the tree does very well in this photo, but I find very important something from Earth in this kind of photos. I think the constellation you focused is just (almost) perfect because of the star colors. Is the line that leads to the tree an artificial satellite?', '2007-06-05 08:00:24.000000', NULL, 1),
(3740811, 522915, 23430, '<td valign="top">Good Colours. Nice and sharp too.</td>', 'Good Colours. Nice and sharp too.', '2007-06-05 08:04:31.000000', NULL, 1),
