INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3744315, 524030, 29011, '<td valign="top">Awesome prop! Looks homemade ;) but only because I wouldn''t imagine seeing something like this for sale.</td>', 'Awesome prop! Looks homemade ;) but only because I wouldn''t imagine seeing something like this for sale.', '2007-06-06 00:21:55.000000', NULL, 1),
(3744318, 519780, 52130, '<td valign="top">...yes. I like those kinds of flowers, they are very photogenic. I planted a bunch of morning glory flowers, and the vines are always reaching out to grab something. I found that they won''t wrap around another morning glory''s leaves 3 inches away, but will only wrap around the bamboo plant that is 1 foot away 0.0 crazy plants.<br/>...anyway, nice job with the lighting and it''s nice that nothing is blown out.</td>', '...yes. I like those kinds of flowers, they are very photogenic. I planted a bunch of morning glory flowers, and the vines are always reaching out to grab something. I found that they won''t wrap around another morning glory''s leaves 3 inches away, but will only wrap around the bamboo plant that is 1 foot away 0.0 crazy plants....anyway, nice job with the lighting and it''s nice that nothing is blown out.', '2007-06-06 00:22:01.000000', NULL, 1),
(3744328, 522664, 22734, '<td valign="top">A beauty of a capture. 7 on first pass.</td>', 'A beauty of a capture. 7 on first pass.', '2007-06-06 00:23:02.000000', NULL, 1),
(3744331, 522474, 22734, '<td valign="top">Interesting.</td>', 'Interesting.', '2007-06-06 00:23:23.000000', NULL, 1),
