(3746403, 523181, 14476, '<td valign="top"><img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=4226" rel="nofollow" target="_blank">gaurawa</a> congratulations on a splendid abstract image.  It''s a real pleasure to look at.</td>', ' gaurawa congratulations on a splendid abstract image.  It''s a real pleasure to look at.', '2007-06-06 10:55:27.000000', NULL, 0),
(3746450, 521382, 74605, '<td valign="top">Photos of bees with flowers are wonderful!  This is really nice and unusual position of the bee add an unusal feel.</td>', 'Photos of bees with flowers are wonderful!  This is really nice and unusual position of the bee add an unusal feel.', '2007-06-06 11:12:52.000000', NULL, 0),
(3746453, 524030, 15305, '<td valign="top">Just brilliant!!! Very creative, well done and with a strong message.<br/>On a lighter side... I wonder if you get pop corn when you plug it in!</td>', 'Just brilliant!!! Very creative, well done and with a strong message.On a lighter side... I wonder if you get pop corn when you plug it in!', '2007-06-06 11:13:13.000000', NULL, 0),
(3746475, 521382, 24454, '<td valign="top">Catherine!!!  Wow!  What a fantastic photo!  Those beautiful soft muted colors make that bee downright 3-dimensional.   Congratulations on this amazing photo.   <br/> <br/></td>', 'Catherine!!!  Wow!  What a fantastic photo!  Those beautiful soft muted colors make that bee downright 3-dimensional.   Congratulations on this amazing photo.    ', '2007-06-06 11:19:25.000000', NULL, 0),
